/* index into glyph tables; -1 if unsupported */
static int aa_index(int64_t c) {
    if (c >= 32 && c <= 126) return (int)c - 32;
    if (c >= 0x410 && c <= 0x44F) return 95 + (int)c - 0x410;
    return -1;
}

/* Anti-aliased text over the live framebuffer. bg is ignored (blend with
   whatever is underneath -> glass-friendly). Returns total advance. */
int64_t k_fb_text_aa(int64_t x, int64_t y, int64_t fg, int64_t bg, const char* s) {
    (void)bg;
    int64_t pen = x;
    for (const char* p = s; *p; p++) {
        int gi = aa_index((int64_t)(unsigned char)*p);
        if (gi < 0) { pen += 6; continue; }
        const aa_glyph_t* g = &AA_META[gi];
        for (int r = 0; r < g->h; r++) {
            for (int c = 0; c < g->w; c++) {
                int cov = AA_DATA[AA_OFF[gi] + r * g->w + c];
                if (cov == 0) continue;
                int64_t px = k_fb_getpixel(pen + g->xoff + c, y + g->yoff + r);
                if (px < 0) continue;
                int32_t br = (int32_t)((px >> 16) & 255), bgc = (int32_t)((px >> 8) & 255), bb = (int32_t)(px & 255);
                int32_t fr = (int32_t)((fg >> 16) & 255), fgc = (int32_t)((fg >> 8) & 255), fb2 = (int32_t)(fg & 255);
                int32_t r2 = br + (((fr - br) * cov) >> 8);
                int32_t g2 = bgc + (((fgc - bgc) * cov) >> 8);
                int32_t b2 = bb + (((fb2 - bb) * cov) >> 8);
                k_fb_putpixel(pen + g->xoff + c, y + g->yoff + r,
                              ((int64_t)r2 << 16) | ((int64_t)g2 << 8) | b2);
            }
        }
        pen += g->adv;
    }
    return pen - x;
}
